import{_ as e}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as a}from"./chunks/ON.DXVlsWbj.js";import{_ as o,a as t,b as n,c as r}from"./chunks/M-S-US6a.BRwbLMSt.js";import{_ as l,o as s,c as p,a3 as d}from"./chunks/framework.g9mfNVRQ.js";const D=JSON.parse('{"title":"Aggiornamento","description":"","frontmatter":{"source_hash":"874eaebd13","source_commit":"7a18e7c","i18n_outdated":true},"headers":[],"relativePath":"it/use/update.md","filePath":"it/use/update.md"}'),c={name:"it/use/update.md"};function m(u,i,g,h,v,b){return s(),p("div",null,[...i[0]||(i[0]=[d('<p>Puoi aggiornare xDrip installando un&#39;altra versione sopra quella attuale senza disinstallarla, nello stesso modo in cui l&#39;hai <a href="./../install/download.html">installato</a> la prima volta.</p><p>Puoi anche usare il meccanismo di aggiornamento interno di xDrip.</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+e+'" style="zoom:75%;"></p><p> Impostazioni<br>  <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_briefcase_download_grey600_48dp.png" style="width:5%;"> xDrip+ Impostazioni di aggiornamento</p></div><p>Le impostazioni di aggiornamento ti permettono di scegliere quali versioni di xDrip ti vengono proposte come aggiornamenti.</p><div class="warning custom-block"><p class="custom-block-title">NON DISINSTALLARE xDRIP+</p><p>Puoi passare a una versione più recente o più vecchia di xDrip semplicemente installandola sopra quella attuale.<br> Disinstallare xDrip può causare una perdita di dati completa e irrecuperabile se non hai fatto un <a href="./../troubleshoot/reinstall.html#reinstall-xdrip">backup</a>.</p></div><p>Solo le versioni ufficiali di xDrip possono usare questa funzione.<br> Se hai installato una <a href="./../install/download.html#forked-versions">versione fork</a>, solo il suo autore può fornire gli aggiornamenti.</p><div class="info custom-block"><p class="custom-block-title">Nota</p><p>L&#39;aggiornamento di xDrip è del tutto trasparente e non richiede alcuna azione particolare sul sensore in uso.<br> Le tue impostazioni verranno mantenute, a meno che un&#39;impostazione specifica non abbia subito una modifica importante.<br> Per precauzione è meglio tenere d&#39;occhio xDrip se hai selezionato una release alpha o nightly.</p></div><p>Dovresti attivare il controllo automatico degli aggiornamenti.</p><div class="admonition xdripitem"><p class="admonition-title">Controllo Aggiornamento automatico <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Ricevi un avviso di nuove uscite app</p></div><p>Se lo lasci disattivato, xDrip ti ricorderà di aggiornare ogni 60 giorni.</p><div class="admonition xdripitem"><p class="admonition-title">Raga...</p><p> Hai il controllo di aggiornamenti disattivato!<br>  Stiamo cercando di correggere i bug e di aggiungere nuove funzionalità a xDrip+.<br>  Ogni 60 giorni questo promemoria ti chiederà di attivare il controllo degli aggiornamenti.</p></div><p>Ci sono tre canali di aggiornamento:</p><ul><li>Stable: versioni rilasciate che hanno dimostrato stabilità e affidabilità</li><li>Beta: versioni candidate a diventare release stabili</li><li>Alpha: versioni in sviluppo</li></ul><p>Un quarto compare solo dopo aver selezionato Alpha (vedi <a href="#getting-the-nightlies-on-automatic-update">sotto</a>):</p><ul><li>Nightly: prototipi per i test</li></ul><p>Le versioni più testate non includono le funzioni e le correzioni più recenti.</p><p>Le versioni meno testate possono contenere bug, ma includono anche le funzioni e le correzioni più recenti.</p><div class="admonition xdripitem"><p class="admonition-title">Aggiorna Canale</p><p> Scegli Trasmissione Stable, Beta o Alpha</p></div><div class="admonition xdripitem"><p class="admonition-title">Aggiorna Canale</p><p> Stable - tried and tested versions<br>  Beta - new features but not fully tested<br>  Alpha - versions for early testing<br>  Nightly - untested raw code - experts only!</p></div><h3 id="getting-the-nightlies-on-automatic-update" tabindex="-1">Ricevere le nightly con l&#39;aggiornamento automatico <a class="header-anchor" href="#getting-the-nightlies-on-automatic-update" aria-label="Permalink to &quot;Ricevere le nightly con l&#39;aggiornamento automatico {#getting-the-nightlies-on-automatic-update}&quot;">​</a></h3><p>Il canale Nightly è nascosto finché non hai selezionato Alpha almeno una volta.</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+e+'" style="zoom:75%;"></p><p> Impostazioni<br>  <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_briefcase_download_grey600_48dp.png" style="width:5%;"> xDrip+ Impostazioni di aggiornamento<br>   Aggiorna Canale</p></div><ol><li>Apri Aggiorna Canale. Se Nightly è nell&#39;elenco, selezionalo e hai finito.</li><li>Se Nightly non è nell&#39;elenco, seleziona Alpha, torna alla schermata principale di xDrip, poi apri di nuovo xDrip+ Impostazioni di aggiornamento e Aggiorna Canale. Ora Nightly è visibile: selezionalo.</li></ol><div class="warning custom-block"><p class="custom-block-title">Nightly è il canale meno testato</p><p>Le build Nightly contengono il codice più recente e meno testato. Sono le prime a ricevere le nuove funzioni, ma anche quelle in cui di solito emergono i bug. Tieni d&#39;occhio xDrip dopo ogni aggiornamento e sii pronto a <a href="#downgrade">tornare indietro</a> installando sopra una release più vecchia.</p></div><p>I controlli degli aggiornamenti avvengono circa ogni 24 ore. Per controllare subito, usa <a href="./3dotsmenu.html#check-for-updated-version">Verifica versione aggiornata</a> nel menu a 3 puntini.</p><p>Nel <a href="https://github.com/NightscoutFoundation/xDrip/releases" target="_blank" rel="noreferrer">repository ufficiale</a> puoi riconoscere l&#39;ultima release dall&#39;etichetta Latest.<br> Puoi scaricare l&#39;ultima release <a href="https://xdrip-plus-updates.appspot.com/stable/xdrip-plus-latest.apk" target="_blank" rel="noreferrer">qui</a>.<br> Tutte le altre hanno l&#39;etichetta Pre-release.</p><img src="'+o+'" style="zoom:75%;"><p>Le funzioni di segnalazione non sono più usate. Se hai bisogno di supporto usa le <a href="https://github.com/NightscoutFoundation/xDrip/discussions" target="_blank" rel="noreferrer">discussioni</a> o <a href="https://www.facebook.com/groups/xDripG5" target="_blank" rel="noreferrer">Facebook</a>.</p><div class="admonition xdripitem"><p class="admonition-title">Segnalazione automatica Crash</p></div><div class="admonition xdripitem"><p class="admonition-title">Attiva telemetria</p></div><p>Il feedback non è più usato. Usalo solo per i complimenti.</p><div class="admonition xdripitem"><p class="admonition-title">Invia Feedback</p></div><h3 id="update" tabindex="-1">Aggiornamento <a class="header-anchor" href="#update" aria-label="Permalink to &quot;Aggiornamento {#update}&quot;">​</a></h3><p>Puoi aggiornare xDrip installando un&#39;altra versione sopra quella attuale senza disinstallarla, nello stesso modo in cui l&#39;hai <a href="./../install/download.html">installato</a> la prima volta.</p><p>Puoi anche usare il meccanismo di aggiornamento interno di xDrip.</p><p>Le notifiche di aggiornamento disponibile scattano in base al canale selezionato.<br> Se hai disattivato il controllo automatico degli aggiornamenti, puoi richiedere un controllo manuale dal <a href="./3dotsmenu.html#check-for-updated-version">menu a 3 puntini</a>.</p><ol><li>Viene mostrato il canale di aggiornamento attuale</li><li>Versione attuale e versione più recente (disponibile)</li><li>Scaricalo ora! avvia il download dell&#39;aggiornamento; al termine del download Android ti chiederà l&#39;autorizzazione all&#39;installazione.</li><li>Puoi disattivare gli aggiornamenti automatici. Ha lo stesso effetto del pulsante di controllo automatico degli aggiornamenti visto sopra.</li><li>Se non usi il downloader interno, il dispositivo userà l&#39;app predefinita per scaricare i file da internet.</li><li>Esci senza fare nulla.</li></ol><img src="'+t+'" style="zoom:75%;"><p>Se selezioni il downloader interno vedrai una barra di avanzamento e, al termine, l&#39;installazione partirà automaticamente.</p><img src="'+n+'" style="zoom:75%;"><p>Se non hai selezionato il downloader interno, il telefono scaricherà il pacchetto da <a href="https://github.com/NightscoutFoundation/xDrip/releases" target="_blank" rel="noreferrer">GitHub</a> e avvierà l&#39;installazione al termine.</p><p>Non dovrebbero servire nuove autorizzazioni.</p><img src="'+r+'" style="zoom:75%;"><p>Dopo l&#39;aggiornamento puoi verificare la versione attuale in <a href="./../troubleshoot/systemstatus.html">Stato del sistema</a>.</p><h3 id="downgrade" tabindex="-1">Tornare a una versione precedente <a class="header-anchor" href="#downgrade" aria-label="Permalink to &quot;Tornare a una versione precedente {#downgrade}&quot;">​</a></h3><p>Non serve disinstallare xDrip per tornare a una versione più vecchia (a meno che tu non stia <a href="./../troubleshoot/reinstall.html">passando dalla versione ufficiale a una fork</a> o viceversa): installa semplicemente la versione che vuoi sopra quella attuale, <a href="./../install/download.html">come hai fatto alla prima installazione</a>.</p><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.11.21" target="_blank" rel="noreferrer"><em>Ultima modifica 23/11/2026</em></a></p>',48)])])}const k=l(c,[["render",m]]);export{D as __pageData,k as default};
